import java.util.*;

class Solution {
    public int minStrain(int[][] heights) {
        int r = heights.length, c = heights[0].length;
        int[][] best = new int[r][c];
        for (int[] row : best) Arrays.fill(row, Integer.MAX_VALUE);
        best[0][0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // {strain, row, col}
        pq.add(new int[]{0, 0, 0});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int s = cur[0], x = cur[1], y = cur[2];
            if (s > best[x][y]) continue; // stale
            if (x == r - 1 && y == c - 1) return s;
            for (int[] d : dirs) {
                int nx = x + d[0], ny = y + d[1];
                if (nx < 0 || ny < 0 || nx >= r || ny >= c) continue;
                int ns = Math.max(s, Math.abs(heights[x][y] - heights[nx][ny])); // worst step so far
                if (ns < best[nx][ny]) { best[nx][ny] = ns; pq.add(new int[]{ns, nx, ny}); }
            }
        }
        return 0;
    }
}

