class Solution:
    def minStrain(self, heights: List[List[int]]) -> int:
        r, c = len(heights), len(heights[0]); best = [[inf] * c for _ in range(r)]; best[0][0] = 0
        h = [(0, 0, 0)]
        while h:
            e, i, j = heappop(h)
            if (i, j) == (r-1, c-1): return e
            if e > best[i][j]: continue
            for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                if 0 <= x < r and 0 <= y < c:
                    ne = max(e, abs(heights[x][y] - heights[i][j]))
                    if ne < best[x][y]: best[x][y] = ne; heappush(h, (ne, x, y))

