function minStrain(heights) {
  const r = heights.length, c = heights[0].length;
  const ok = lim => { const s = heights.map(x => x.map(() => false)), st = [[0, 0]]; s[0][0] = true;
    while (st.length) { const [i, j] = st.pop(); if (i === r-1 && j === c-1) return true;
      for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]]) if (x >= 0 && x < r && y >= 0 && y < c && !s[x][y] && Math.abs(heights[x][y] - heights[i][j]) <= lim) { s[x][y] = true; st.push([x, y]); } }
    return false; };
  let lo = 0, hi = 1000000;
  while (lo < hi) { const m = Math.floor((lo + hi) / 2); if (ok(m)) hi = m; else lo = m + 1; }
  return lo;
}
